package controller
import("testing";"strings";"net/http";"github.com/goodrain/rainbond/pkg/vmrestore")
func TestIndependentV11UnknownHTTPDiscardsContradictoryReadyDTO(t *testing.T){for _,err:=range []error{vmrestore.ErrRestoreUnknown,vmrestore.ErrRestorePending}{s:=&restoreHTTPService{err:err,dto:vmrestore.RestoreOperationDTO{Complete:true,Applied:true,Phase:"complete",SourceConfigReady:true}};w:=snapshotHTTPRequest(restoreHTTPRouter(&VMRestoreController{service:s}),"POST","/vm-restores/op/steps/halt",`{}`,true);body:=w.Body.String();if w.Code!=http.StatusAccepted||!strings.Contains(body,`"complete":false`)||strings.Contains(body,`"source_config_ready":true`)||strings.Contains(body,`"complete":true`){t.Fatal("pending became ready",w.Code,body)}}}
func TestIndependentV11StrictInputNeverCallsFacade(t *testing.T){s:=&restoreHTTPService{};router:=restoreHTTPRouter(&VMRestoreController{service:s});for _,body:=range []string{`null`,`{"target_vm_uid":"untrusted"}`,`{"operation_epoch":"untrusted"}`,`{"config":{"userdata":null}}`,`{} {}`}{w:=snapshotHTTPRequest(router,"POST","/vm-restores/op/steps/prepare",body,true);if w.Code!=400{t.Fatal("unsafe body accepted",w.Code)}};if s.calls!=0{t.Fatal("invalid proof reached facade")}}
